# Modular Microservices Feature Flag Management System

Below is a design for a Python-based feature flag management system with the three requested components. This architecture follows microservices principles with clear separation of concerns.

## System Architecture Overview

```
┌───────────────────────────────────────────────────────────────┐
│                     Feature Flag Management System             │
├───────────────────┬───────────────────┬───────────────────────┤
│   Evaluation      │   Config Sync    │   Audit Logging       │
│   Engine          │   Service        │   Subsystem           │
└───────────────────┴───────────────────┴───────────────────────┘
```

## 1. Evaluation Engine

```python
# evaluation_engine/engine.py
from typing import Dict, Any, Optional
from dataclasses import dataclass
from enum import Enum, auto
import json
from abc import ABC, abstractmethod

class EvaluationResult(Enum):
    ENABLED = auto()
    DISABLED = auto()
    ERROR = auto()

@dataclass
class UserContext:
    user_id: str
    user_type: str
    attributes: Dict[str, Any]  # Additional user attributes
    environment: str
    region: str

class SegmentRule(ABC):
    @abstractmethod
    def matches(self, context: UserContext) -> bool:
        pass

class SimpleSegmentRule(SegmentRule):
    def __init__(self, condition: str, value: Any):
        self.condition = condition
        self.value = value

    def matches(self, context: UserContext) -> bool:
        try:
            # Simple evaluation of conditions like "user_type == 'premium'"
            # In a real system, this would be more sophisticated
            left = context.attributes.get(self.condition.split('__')[0])
            if left is None:
                return False

            if '__' in self.condition:
                key, op = self.condition.split('__')
                if op == 'contains':
                    return self.value in left
                elif op == 'starts_with':
                    return str(left).startswith(self.value)
                else:
                    return left == self.value
            return left == self.value
        except:
            return False

class FeatureFlag:
    def __init__(self, name: str, default_value: bool = False):
        self.name = name
        self.default_value = default_value
        self.rules: Dict[str, SegmentRule] = {}
        self.variants: Dict[str, Any] = {}

    def add_rule(self, rule_name: str, rule: SegmentRule):
        self.rules[rule_name] = rule

    def add_variant(self, variant_name: str, value: Any):
        self.variants[variant_name] = value

class EvaluationEngine:
    def __init__(self):
        self.flags: Dict[str, FeatureFlag] = {}

    def register_flag(self, flag: FeatureFlag):
        self.flags[flag.name] = flag

    def evaluate(self, flag_name: str, context: UserContext) -> EvaluationResult:
        if flag_name not in self.flags:
            return EvaluationResult.ERROR

        flag = self.flags[flag_name]

        # Check all rules
        for rule_name, rule in flag.rules.items():
            if rule.matches(context):
                # In a real system, we'd track which rule matched
                return EvaluationResult.ENABLED

        return EvaluationResult.DISABLED

    def get_variant(self, flag_name: str, context: UserContext) -> Optional[Any]:
        result = self.evaluate(flag_name, context)
        if result != EvaluationResult.ENABLED:
            return None

        # Default to first variant if no specific variant is selected
        if not flag.variants:
            return None

        return next(iter(flag.variants.values()))
```

## 2. Dynamic Configuration Sync Service

```python
# config_sync/service.py
import requests
import time
from typing import Dict, Any
import json
from pathlib import Path
import git
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import threading
import logging

class ConfigSyncService:
    def __init__(self, repo_url: str, config_path: str = "config/flags.json"):
        self.repo_url = repo_url
        self.config_path = config_path
        self.current_config: Dict[str, Any] = {}
        self.config_lock = threading.Lock()
        self.running = False
        self.observer = None
        self.logger = logging.getLogger(__name__)

    def clone_repo(self):
        """Clone the git repository if it doesn't exist"""
        try:
            git.Repo.clone_from(self.repo_url, ".git")
            self.logger.info("Successfully cloned repository")
        except git.GitCommandError as e:
            self.logger.error(f"Failed to clone repository: {e}")
            raise

    def load_config(self) -> Dict[str, Any]:
        """Load the current configuration from the git repository"""
        try:
            repo = git.Repo(".git")
            config_file = repo.git.show(f"{self.config_path}:{self.config_path}")

            # Parse the JSON content
            return json.loads(config_file)
        except Exception as e:
            self.logger.error(f"Failed to load config: {e}")
            return {}

    def sync_config(self):
        """Poll the git repository for changes"""
        while self.running:
            try:
                new_config = self.load_config()

                with self.config_lock:
                    if new_config != self.current_config:
                        self.current_config = new_config
                        self.logger.info("Configuration updated successfully")
                        # Here you would typically notify other services
                        # or trigger a flag reload in the evaluation engine
            except Exception as e:
                self.logger.error(f"Error during config sync: {e}")

            time.sleep(30)  # Poll every 30 seconds

    def start(self):
        """Start the configuration sync service"""
        if not Path(".git").exists():
            self.clone_repo()

        self.running = True
        self.observer = Observer()
        self.observer.schedule(FileSystemEventHandler(), path=".", recursive=True)

        # Start the sync thread
        sync_thread = threading.Thread(target=self.sync_config, daemon=True)
        sync_thread.start()

        self.observer.start()
        self.logger.info("Configuration sync service started")

    def stop(self):
        """Stop the configuration sync service"""
        self.running = False
        if self.observer:
            self.observer.stop()
            self.observer.join()
        self.logger.info("Configuration sync service stopped")

    def get_current_config(self) -> Dict[str, Any]:
        """Get the current configuration (thread-safe)"""
        with self.config_lock:
            return self.current_config.copy()
```

## 3. Audit Logging Subsystem

```python
# audit_logging/subsystem.py
import logging
from datetime import datetime
from typing import Dict, Any
import json
from abc import ABC, abstractmethod

class AuditLogger(ABC):
    @abstractmethod
    def log(self, event_type: str, data: Dict[str, Any]):
        pass

class FileAuditLogger(AuditLogger):
    def __init__(self, log_file: str = "audit.log"):
        self.log_file = log_file
        self.logger = logging.getLogger(__name__)

    def log(self, event_type: str, data: Dict[str, Any]):
        """Log an audit event to a file"""
        try:
            event = {
                "timestamp": datetime.utcnow().isoformat(),
                "event_type": event_type,
                "data": data
            }

            with open(self.log_file, "a") as f:
                f.write(json.dumps(event) + "\n")

            self.logger.info(f"Logged audit event: {event_type}")
        except Exception as e:
            self.logger.error(f"Failed to log audit event: {e}")

class DatabaseAuditLogger(AuditLogger):
    def __init__(self, db_connection):
        self.db_connection = db_connection
        self.logger = logging.getLogger(__name__)

    def log(self, event_type: str, data: Dict[str, Any]):
        """Log an audit event to a database"""
        try:
            # In a real implementation, this would use your database connection
            # to insert the event into an audit table
            self.logger.info(f"Database audit event logged: {event_type}")
        except Exception as e:
            self.logger.error(f"Failed to log database audit event: {e}")

class AuditSubsystem:
    def __init__(self):
        self.loggers: Dict[str, AuditLogger] = {
            "file": FileAuditLogger(),
            "database": None  # Would be initialized with a connection
        }
        self.current_logger = "file"

    def set_logger(self, logger_name: str):
        """Set the active logger"""
        if logger_name in self.loggers:
            self.current_logger = logger_name
        else:
            raise ValueError(f"Unknown logger: {logger_name}")

    def log_flag_change(self, flag_name: str, old_value: Any, new_value: Any,
                       changed_by: str, context: Dict[str, Any] = None):
        """Log a flag change event"""
        event_data = {
            "flag_name": flag_name,
            "old_value": old_value,
            "new_value": new_value,
            "changed_by": changed_by,
            "context": context or {}
        }

        self.loggers[self.current_logger].log("flag_change", event_data)

    def log_evaluation(self, flag_name: str, result: str, context: Dict[str, Any]):
        """Log a feature flag evaluation"""
        event_data = {
            "flag_name": flag_name,
            "result": result,
            "context": context
        }

        self.loggers[self.current_logger].log("flag_evaluation", event_data)
